(()=>{'use strict';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const date=t=>new Date(t).toLocaleDateString('ar-SA',{calendar:'gregory',timeZone:'Asia/Riyadh'});const money=c=>(c/100).toLocaleString('ar-SA',{minimumFractionDigits:2,maximumFractionDigits:2})+' ريال';document.querySelector('#invoice-print').addEventListener('click',()=>window.print());async function show(){const target=document.querySelector('#invoice-view');try{const id=new URLSearchParams(location.search).get('id');if(!id)throw Error('حدد الفاتورة المطلوبة.');const response=await fetch('/api/invoices?id='+encodeURIComponent(id),{credentials:'same-origin',cache:'no-store'}),data=await response.json();if(!response.ok)throw Error(data.error||'تعذر تحميل الفاتورة.');const i=data.invoice;document.title=i.number+' — رِجعة';target.innerHTML=`<header><img src="/brand-logo.png" alt="رِجعة"><div><h1>فاتورة اشتراك</h1><p dir="ltr">${esc(i.number)}</p><strong>${({issued:'بانتظار السداد',paid:'مدفوعة',cancelled:'ملغاة'})[i.status]}</strong></div></header><div class="meta"><div><small>صاحب الحساب</small><strong>${esc(i.customer)}</strong><p>${esc(i.business)}</p><p dir="ltr">${esc(i.account)}</p></div><div><small>تاريخ الإصدار</small><strong>${date(i.created)}</strong>${i.paidAt?'<p>تاريخ السداد: '+date(i.paidAt)+'</p>':''}</div></div><table><thead><tr><th>الخدمة</th><th>فترة الخدمة</th><th>المبلغ</th></tr></thead><tbody><tr><td>اشتراك رِجعة · ${esc(i.planName)}<p>${i.period==='year'?'سنوي · ١٢ شهرًا':'شهري · شهر واحد'}</p></td><td>${date(i.start)}<br>إلى ${date(i.end)}</td><td>${money(i.amountCents)}</td></tr></tbody></table><div class="total">الإجمالي: <strong>${money(i.amountCents)}</strong></div>${i.notes?'<p class="notes">'+esc(i.notes)+'</p>':''}${i.cancelReason?'<p class="notes">سبب الإلغاء: '+esc(i.cancelReason)+'</p>':''}<p class="notice">فاتورة خدمة اشتراك، وليست فاتورة ضريبية. اعتماد السداد يُسجل بواسطة الإدارة. إصدار هذه الفاتورة لا يغيّر حالة الاشتراك.</p>`;document.querySelector('#invoice-print').disabled=false;}catch(e){target.textContent=e.message;}}show();})();
